21: #ifndef ASYNCXX_H_
22: # error "Do not include this header directly, include <async++.h> instead."
23: #endif
24: 
25: namespace async {
26: 
27: // Exception thrown when an event_task is destroyed without setting a value
28: struct LIBASYNC_EXPORT_EXCEPTION abandoned_event_task {};
29: 
30: namespace detail {
31: 
32: // Common code for task and shared_task
33: template<typename Result>
34: class basic_task {
35: 	// Reference counted internal task object
36: 	detail::task_ptr internal_task;
37: 
38: 	// Real result type, with void turned into fake_void
39: 	typedef typename void_to_fake_void<Result>::type internal_result;
40: 
41: 	// Type-specific task object
42: 	typedef task_result<internal_result> internal_task_type;
43: 
44: 	// Friend access
45: 	friend async::task<Result>;
46: 	friend async::shared_task<Result>;
47: 	template<typename T>
48: 	friend typename T::internal_task_type* get_internal_task(const T& t);
49: 	template<typename T>
50: 	friend void set_internal_task(T& t, task_ptr p);
51: 
52: 	// Common code for get()
53: 	void get_internal() const
54: 	{
55: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty task object");
56: 
57: 		// If the task was canceled, throw the associated exception
58: 		get_internal_task(*this)->wait_and_throw();
59: 	}
60: 
61: 	// Common code for then()
62: 	template<typename Sched, typename Func, typename Parent>
63: 	typename continuation_traits<Parent, Func>::task_type then_internal(Sched& sched, Func&& f, Parent&& parent) const
64: 	{
65: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty task object");
66: 
67: 		// Save a copy of internal_task because it might get moved into exec_func
68: 		task_base* my_internal = internal_task.get();
69: 
70: 		// Create continuation
71: 		typedef continuation_traits<Parent, Func> traits;
72: 		typedef typename void_to_fake_void<typename traits::task_type::result_type>::type cont_internal_result;
73: 		typedef continuation_exec_func<Sched, typename std::decay<Parent>::type, cont_internal_result, typename traits::decay_func, typename traits::is_value_cont, is_task<typename traits::result_type>::value> exec_func;
74: 		typename traits::task_type cont;
75: 		set_internal_task(cont, task_ptr(new task_func<Sched, exec_func, cont_internal_result>(std::forward<Func>(f), std::forward<Parent>(parent))));
76: 
77: 		// Add the continuation to this task
78: 		// Avoid an expensive ref-count modification since the task isn't shared yet
79: 		get_internal_task(cont)->add_ref_unlocked();
80: 		get_internal_task(cont)->sched = std::addressof(sched);
81: 		my_internal->add_continuation(sched, task_ptr(get_internal_task(cont)));
82: 
83: 		return cont;
84: 	}
85: 
86: public:
87: 	// Task result type
88: 	typedef Result result_type;
89: 
90: 	// Check if this task is not empty
91: 	bool valid() const
92: 	{
93: 		return internal_task != nullptr;
94: 	}
95: 
96: 	// Query whether the task has finished executing
97: 	bool ready() const
98: 	{
99: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty task object");
100: 		return internal_task->ready();
101: 	}
102: 
103: 	// Query whether the task has been canceled with an exception
104: 	bool canceled() const
105: 	{
106: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty task object");
107: 		return internal_task->state.load(std::memory_order_acquire) == task_state::canceled;
108: 	}
109: 
110: 	// Wait for the task to complete
111: 	void wait() const
112: 	{
113: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty task object");
114: 		internal_task->wait();
115: 	}
116: 
117: 	// Get the exception associated with a canceled task
118: 	std::exception_ptr get_exception() const
119: 	{
120: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty task object");
121: 		if (internal_task->wait() == task_state::canceled)
122: 			return get_internal_task(*this)->get_exception();
123: 		else
124: 			return std::exception_ptr();
125: 	}
126: };
127: 
128: // Common code for event_task specializations
129: template<typename Result>
130: class basic_event {
131: 	// Reference counted internal task object
132: 	detail::task_ptr internal_task;
133: 
134: 	// Real result type, with void turned into fake_void
135: 	typedef typename detail::void_to_fake_void<Result>::type internal_result;
136: 
137: 	// Type-specific task object
138: 	typedef detail::task_result<internal_result> internal_task_type;
139: 
140: 	// Friend access
141: 	friend async::event_task<Result>;
142: 	template<typename T>
143: 	friend typename T::internal_task_type* get_internal_task(const T& t);
144: 
145: 	// Common code for set()
146: 	template<typename T>
147: 	bool set_internal(T&& result) const
148: 	{
149: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty event_task object");
150: 
151: 		// Only allow setting the value once
152: 		detail::task_state expected = detail::task_state::pending;
153: 		if (!internal_task->state.compare_exchange_strong(expected, detail::task_state::locked, std::memory_order_acquire, std::memory_order_relaxed))
154: 			return false;
155: 
156: 		LIBASYNC_TRY {
157: 			// Store the result and finish
158: 			get_internal_task(*this)->set_result(std::forward<T>(result));
159: 			internal_task->finish();
160: 		} LIBASYNC_CATCH(...) {
161: 			// At this point we have already committed to setting a value, so
162: 			// we can't return the exception to the caller. If we did then it
163: 			// could cause concurrent set() calls to fail, thinking a value has
164: 			// already been set. Instead, we simply cancel the task with the
165: 			// exception we just got.
166: 			get_internal_task(*this)->cancel_base(std::current_exception());
167: 		}
168: 		return true;
169: 	}
170: 
171: public:
172: 	// Movable but not copyable
173: 	basic_event(basic_event&& other) LIBASYNC_NOEXCEPT
174: 		: internal_task(std::move(other.internal_task)) {}
175: 	basic_event& operator=(basic_event&& other) LIBASYNC_NOEXCEPT
176: 	{
177: 		internal_task = std::move(other.internal_task);
178: 		return *this;
179: 	}
180: 
181: 	// Main constructor
182: 	basic_event()
183: 		: internal_task(new internal_task_type)
184: 	{
185: 		internal_task->event_task_got_task = false;
186: 	}
187: 
188: 	// Cancel events if they are destroyed before they are set
189: 	~basic_event()
190: 	{
191: 		// This check isn't thread-safe but set_exception does a proper check
192: 		if (internal_task && !internal_task->ready() && !internal_task->is_unique_ref(std::memory_order_relaxed)) {
193: #ifdef LIBASYNC_NO_EXCEPTIONS
194: 			// This will result in an abort if the task result is read
195: 			set_exception(std::exception_ptr());
196: #else
197: 			set_exception(std::make_exception_ptr(abandoned_event_task()));
198: #endif
199: 		}
200: 	}
201: 
202: 	// Get the task linked to this event. This can only be called once.
203: 	task<Result> get_task()
204: 	{
205: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty event_task object");
206: 		LIBASYNC_ASSERT(!internal_task->event_task_got_task, std::logic_error, "get_task() called twice on event_task");
207: 
208: 		// Even if we didn't trigger an assert, don't return a task if one has
209: 		// already been returned.
210: 		task<Result> out;
211: 		if (!internal_task->event_task_got_task)
212: 			set_internal_task(out, internal_task);
213: 		internal_task->event_task_got_task = true;
214: 		return out;
215: 	}
216: 
217: 	// Cancel the event with an exception and cancel continuations
218: 	bool set_exception(std::exception_ptr except) const
219: 	{
220: 		LIBASYNC_ASSERT(internal_task, std::invalid_argument, "Use of empty event_task object");
221: 
222: 		// Only allow setting the value once
223: 		detail::task_state expected = detail::task_state::pending;
224: 		if (!internal_task->state.compare_exchange_strong(expected, detail::task_state::locked, std::memory_order_acquire, std::memory_order_relaxed))
225: 			return false;
226: 
227: 		// Cancel the task
228: 		get_internal_task(*this)->cancel_base(std::move(except));
229: 		return true;
230: 	}
231: };
232: 
233: } // namespace detail
234: 
235: template<typename Result>
236: class task: public detail::basic_task<Result> {
237: public:
238: 	// Movable but not copyable
239: 	task() = default;
240: 	task(task&& other) LIBASYNC_NOEXCEPT
241: 		: detail::basic_task<Result>(std::move(other)) {}
242: 	task& operator=(task&& other) LIBASYNC_NOEXCEPT
243: 	{
244: 		detail::basic_task<Result>::operator=(std::move(other));
245: 		return *this;
246: 	}
247: 
248: 	// Get the result of the task
249: 	Result get()
250: 	{
251: 		this->get_internal();
252: 
253: 		// Move the internal state pointer so that the task becomes invalid,
254: 		// even if an exception is thrown.
255: 		detail::task_ptr my_internal = std::move(this->internal_task);
256: 		return detail::fake_void_to_void(static_cast<typename task::internal_task_type*>(my_internal.get())->get_result(*this));
257: 	}
258: 
259: 	// Add a continuation to the task
260: 	template<typename Sched, typename Func>
261: 	typename detail::continuation_traits<task, Func>::task_type then(Sched& sched, Func&& f)
262: 	{
263: 		return this->then_internal(sched, std::forward<Func>(f), std::move(*this));
264: 	}
265: 	template<typename Func>
266: 	typename detail::continuation_traits<task, Func>::task_type then(Func&& f)
267: 	{
268: 		return then(::async::default_scheduler(), std::forward<Func>(f));
269: 	}
270: 
271: 	// Create a shared_task from this task
272: 	shared_task<Result> share()
273: 	{
274: 		LIBASYNC_ASSERT(this->internal_task, std::invalid_argument, "Use of empty task object");
275: 
276: 		shared_task<Result> out;
277: 		detail::set_internal_task(out, std::move(this->internal_task));
278: 		return out;
279: 	}
280: };
281: 
282: template<typename Result>
283: class shared_task: public detail::basic_task<Result> {
284: 	// get() return value: const Result& -or- void
285: 	typedef typename std::conditional<
286: 		std::is_void<Result>::value,
287: 		void,
288: 		typename std::add_lvalue_reference<
289: 			typename std::add_const<Result>::type
290: 		>::type
291: 	>::type get_result;
292: 
293: public:
294: 	// Movable and copyable
295: 	shared_task() = default;
296: 
297: 	// Get the result of the task
298: 	get_result get() const
299: 	{
300: 		this->get_internal();
301: 		return detail::fake_void_to_void(detail::get_internal_task(*this)->get_result(*this));
302: 	}
303: 
304: 	// Add a continuation to the task
305: 	template<typename Sched, typename Func>
306: 	typename detail::continuation_traits<shared_task, Func>::task_type then(Sched& sched, Func&& f) const
307: 	{
308: 		return this->then_internal(sched, std::forward<Func>(f), *this);
309: 	}
310: 	template<typename Func>
311: 	typename detail::continuation_traits<shared_task, Func>::task_type then(Func&& f) const
312: 	{
313: 		return then(::async::default_scheduler(), std::forward<Func>(f));
314: 	}
315: };
316: 
317: // Special task type which can be triggered manually rather than when a function executes.
318: template<typename Result>
319: class event_task: public detail::basic_event<Result> {
320: public:
321: 	// Movable but not copyable
322: 	event_task() = default;
323: 	event_task(event_task&& other) LIBASYNC_NOEXCEPT
324: 		: detail::basic_event<Result>(std::move(other)) {}
325: 	event_task& operator=(event_task&& other) LIBASYNC_NOEXCEPT
326: 	{
327: 		detail::basic_event<Result>::operator=(std::move(other));
328: 		return *this;
329: 	}
330: 
331: 	// Set the result of the task, mark it as completed and run its continuations
332: 	bool set(const Result& result) const
333: 	{
334: 		return this->set_internal(result);
335: 	}
336: 	bool set(Result&& result) const
337: 	{
338: 		return this->set_internal(std::move(result));
339: 	}
340: };
341: 
342: // Specialization for references
343: template<typename Result>
344: class event_task<Result&>: public detail::basic_event<Result&> {
345: public:
346: 	// Movable but not copyable
347: 	event_task() = default;
348: 	event_task(event_task&& other) LIBASYNC_NOEXCEPT
349: 		: detail::basic_event<Result&>(std::move(other)) {}
