28: // Task states
29: enum class task_state: unsigned char {
30: 	pending, // Task has not completed yet
31: 	locked, // Task is locked (used by event_task to prevent double set)
32: 	unwrapped, // Task is waiting for an unwrapped task to finish
33: 	completed, // Task has finished execution and a result is available
34: 	canceled // Task has been canceled and an exception is available
35: };
36: 
37: // Determine whether a task is in a final state
38: inline bool is_finished(task_state s)
39: {
40: 	return s == task_state::completed || s == task_state::canceled;
41: }
42: 
43: // Virtual function table used to allow dynamic dispatch for task objects.
44: // While this is very similar to what a compiler would generate with virtual
45: // functions, this scheme was found to result in significantly smaller
46: // generated code size.
47: struct task_base_vtable {
48: 	// Destroy the function and result
49: 	void (*destroy)(task_base*) LIBASYNC_NOEXCEPT;
50: 
51: 	// Run the associated function
52: 	void (*run)(task_base*) LIBASYNC_NOEXCEPT;
53: 
54: 	// Cancel the task with an exception
55: 	void (*cancel)(task_base*, std::exception_ptr&&) LIBASYNC_NOEXCEPT;
56: 
57: 	// Schedule the task using its scheduler
58: 	void (*schedule)(task_base* parent, task_ptr t);
59: };
60: 
61: // Type-generic base task object
62: struct task_base_deleter;
63: struct LIBASYNC_CACHELINE_ALIGN task_base: public ref_count_base<task_base, task_base_deleter> {
64: 	// Task state
65: 	std::atomic<task_state> state;
66: 
67: 	// Whether get_task() was already called on an event_task
68: 	bool event_task_got_task;
69: 
70: 	// Vector of continuations
71: 	continuation_vector continuations;
72: 
73: 	// Virtual function table used for dynamic dispatch
74: 	const task_base_vtable* vtable;
75: 
76: 	// Use aligned memory allocation
77: 	static void* operator new(std::size_t size)
78: 	{
79: 		return aligned_alloc(size, LIBASYNC_CACHELINE_SIZE);
80: 	}
81: 	static void operator delete(void* ptr)
82: 	{
83: 		aligned_free(ptr);
84: 	}
85: 
86: 	// Initialize task state
87: 	task_base()
88: 		: state(task_state::pending) {}
89: 
90: 	// Check whether the task is ready and include an acquire barrier if it is
91: 	bool ready() const
92: 	{
93: 		return is_finished(state.load(std::memory_order_acquire));
94: 	}
95: 
96: 	// Run a single continuation
97: 	template<typename Sched>
98: 	void run_continuation(Sched& sched, task_ptr&& cont)
99: 	{
100: 		LIBASYNC_TRY {
101: 			detail::schedule_task(sched, cont);
102: 		} LIBASYNC_CATCH(...) {
103: 			// This is suboptimal, but better than letting the exception leak
104: 			cont->vtable->cancel(cont.get(), std::current_exception());
105: 		}
106: 	}
107: 
108: 	// Run all of the task's continuations after it has completed or canceled.
109: 	// The list of continuations is emptied and locked to prevent any further
110: 	// continuations from being added.
111: 	void run_continuations()
112: 	{
113: 		continuations.flush_and_lock([this](task_ptr t) {
114: 			const task_base_vtable* vtable_ptr = t->vtable;
115: 			vtable_ptr->schedule(this, std::move(t));
116: 		});
117: 	}
118: 
119: 	// Add a continuation to this task
120: 	template<typename Sched>
121: 	void add_continuation(Sched& sched, task_ptr cont)
122: 	{
123: 		// Check for task completion
124: 		task_state current_state = state.load(std::memory_order_relaxed);
125: 		if (!is_finished(current_state)) {
126: 			// Try to add the task to the continuation list. This can fail only
127: 			// if the task has just finished, in which case we run it directly.
128: 			if (continuations.try_add(std::move(cont)))
129: 				return;
130: 		}
131: 
132: 		// Otherwise run the continuation directly
133: 		std::atomic_thread_fence(std::memory_order_acquire);
134: 		run_continuation(sched, std::move(cont));
135: 	}
136: 
137: 	// Finish the task after it has been executed and the result set
138: 	void finish()
139: 	{
140: 		state.store(task_state::completed, std::memory_order_release);
141: 		run_continuations();
142: 	}
143: 
144: 	// Wait for the task to finish executing
145: 	task_state wait()
146: 	{
147: 		task_state s = state.load(std::memory_order_acquire);
148: 		if (!is_finished(s)) {
149: 			wait_for_task(this);
150: 			s = state.load(std::memory_order_relaxed);
151: 		}
152: 		return s;
153: 	}
154: };
