165: // Result type-specific task object
166: template<typename Result>
167: struct task_result_holder: public task_base {
168: 	union {
169: 		alignas(Result) std::uint8_t result[sizeof(Result)];
170: 		alignas(std::exception_ptr) std::uint8_t except[sizeof(std::exception_ptr)];
171: 
172: 		// Scheduler that should be used to schedule this task. The scheduler
173: 		// type has been erased and is held by vtable->schedule.
174: 		void* sched;
175: 	};
176: 
177: 	template<typename T>
178: 	void set_result(T&& t)
179: 	{
180: 		new(&result) Result(std::forward<T>(t));
181: 	}
182: 
183: 	// Return a result using an lvalue or rvalue reference depending on the task
184: 	// type. The task parameter is not used, it is just there for overload resolution.
185: 	template<typename T>
186: 	Result&& get_result(const task<T>&)
187: 	{
188: 		return std::move(*reinterpret_cast<Result*>(&result));
189: 	}
190: 	template<typename T>
191: 	const Result& get_result(const shared_task<T>&)
192: 	{
193: 		return *reinterpret_cast<Result*>(&result);
194: 	}
