196: 	// Destroy the result
197: 	~task_result_holder()
198: 	{
199: 		// Result is only present if the task completed successfully
200: 		if (state.load(std::memory_order_relaxed) == task_state::completed)
201: 			reinterpret_cast<Result*>(&result)->~Result();
202: 	}
