256: template<typename Result>
257: struct task_result: public task_result_holder<Result> {
258: 	// Virtual function table for task_result
259: 	static const task_base_vtable vtable_impl;
260: 	task_result()
261: 	{
262: 		this->vtable = &vtable_impl;
263: 	}
