265: 	// Destroy the exception
266: 	~task_result()
267: 	{
268: 		// Exception is only present if the task was canceled
269: 		if (this->state.load(std::memory_order_relaxed) == task_state::canceled)
270: 			reinterpret_cast<std::exception_ptr*>(&this->except)->~exception_ptr();
271: 	}
