421: 	~task_func()
422: 	{
423: 		// If the task hasn't completed yet, destroy the function object. Note
424: 		// that an unwrapped task has already destroyed its function object.
425: 		if (this->state.load(std::memory_order_relaxed) == task_state::pending)
426: 			this->destroy_func();
