    },
    {
      "name": "并行算法",
      "description": "提供 parallel_for（并行遍历区间元素）、parallel_reduce（并行归约）和 parallel_invoke（同时执行多个可调用对象），支持自动粒度调整与分区器（partitioner）策略。",
      "evidence": ["include/async++/parallel_for.h", "include/async++/parallel_reduce.h", "include/async++/parallel_invoke.h", "include/async++/partitioner.h", "include/async++/range.h"]
